<?php
declare(strict_types=1);
function install_schema(PDO $db): void {
    $queries = [
        'CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM(\'user\',\'admin\') NOT NULL DEFAULT \'user\',status ENUM(\'active\',\'disabled\') NOT NULL DEFAULT \'active\',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_login_at DATETIME NULL,INDEX idx_users_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci',
        'CREATE TABLE IF NOT EXISTS auth_sessions (token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,csrf_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_session_user(user_id),INDEX idx_session_exp(expires_at),FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
        'CREATE TABLE IF NOT EXISTS apps (slug VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,name VARCHAR(65) NOT NULL,url VARCHAR(2048) NOT NULL,description VARCHAR(140) NOT NULL DEFAULT \'\',category VARCHAR(35) NOT NULL DEFAULT \'Aplicativos\',icon VARCHAR(20) NOT NULL DEFAULT \'🔗\',enabled TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
        'CREATE TABLE IF NOT EXISTS grants (user_id BIGINT UNSIGNED NOT NULL,app_slug VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,expires_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,app_slug),INDEX idx_grant_exp(expires_at),FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY (app_slug) REFERENCES apps(slug) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
        'CREATE TABLE IF NOT EXISTS auth_throttle (key_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,attempts INT UNSIGNED NOT NULL,window_start DATETIME NOT NULL,blocked_until DATETIME NULL, INDEX idx_blocked(blocked_until)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
        'CREATE TABLE IF NOT EXISTS audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED NULL,action VARCHAR(90) NOT NULL,details VARCHAR(200) NOT NULL DEFAULT \'\',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_time(created_at),INDEX idx_audit_actor(actor_user_id),FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'
    ];
    foreach ($queries as $sql) $db->exec($sql);
}
